'use strict';

const express = require('express');

const ALLOWED_METHODS = ['GET', 'POST'];

function createApp() {
  const app = express();

  app.use(express.json());

  const widgets = [];

  app.get('/widgets', (req, res) => {
    res.json({ widgets });
  });

  app.post('/widgets', (req, res) => {
    const { name } = req.body || {};
    if (!name) {
      return res.status(400).json({ error: 'bad_request', message: '"name" is required' });
    }
    const widget = { id: widgets.length + 1, name };
    widgets.push(widget);
    res.status(201).json(widget);
  });

  // Method not allowed: path exists but method is not routed.
  app.all('/widgets', (req, res) => {
    res.set('Allow', ALLOWED_METHODS.join(', '));
    res.status(405).json({
      error: 'method_not_allowed',
      method: req.method,
      path: req.originalUrl,
      allow: ALLOWED_METHODS,
    });
  });

  // Not found: unmatched routes.
  app.use((req, res) => {
    res.status(404).json({ error: 'not_found', path: req.originalUrl });
  });

  return app;
}

module.exports = { createApp, ALLOWED_METHODS };

