'use strict';

const request = require('supertest');
const { createApp } = require('../src/app');

describe('route hygiene', () => {
  let app;

  beforeEach(() => {
    app = createApp();
  });

  describe('happy path', () => {
    test('GET /widgets returns list', async () => {
      const res = await request(app).get('/widgets');
      expect(res.status).toBe(200);
      expect(res.body).toEqual({ widgets: [] });
    });

    test('POST /widgets creates a widget', async () => {
      const res = await request(app).post('/widgets').send({ name: 'gear' });
      expect(res.status).toBe(201);
      expect(res.body).toMatchObject({ id: 1, name: 'gear' });
    });
  });

  describe('404 for unmatched routes', () => {
    const unmatched = [
      ['GET', '/nope'],
      ['GET', '/widgets/123'],
      ['POST', '/deeply/nested/path'],
      ['DELETE', '/unknown'],
    ];

    for (const [method, url] of unmatched) {
      test(`${method} ${url} -> 404 JSON with echoed path`, async () => {
        const res = await request(app)[method.toLowerCase()](url);
        expect(res.status).toBe(404);
        expect(res.headers['content-type']).toMatch(/application\/json/);
        expect(res.body).toEqual({ error: 'not_found', path: url });
      });
    }
  });

  describe('405 for wrong method on existing route', () => {
    const wrongMethods = [
      ['put', 'PUT'],
      ['delete', 'DELETE'],
      ['patch', 'PATCH'],
    ];

    for (const [fn, method] of wrongMethods) {
      test(`${method} /widgets -> 405 with Allow header`, async () => {
        const res = await request(app)[fn]('/widgets').send({});
        expect(res.status).toBe(405);
        expect(res.headers.allow).toBe('GET, POST');
        expect(res.headers['content-type']).toMatch(/application\/json/);
        expect(res.body.error).toBe('method_not_allowed');
        expect(res.body.path).toBe('/widgets');
      });
    }

    test('Allow header lists exactly the supported methods', async () => {
      const res = await request(app).patch('/widgets');
      const allowed = res.headers.allow.split(', ').sort();
      expect(allowed).toEqual(['GET', 'POST']);
    });
  });
});

